package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.dto.*;import com.digitalbase.ticketing.enums.ProductStatus;import com.digitalbase.ticketing.enums.TicketStatus;import com.digitalbase.ticketing.exception.DuplicateResourceException; // 👈 အသစ် Import လုပ်ထားပါသည်import com.digitalbase.ticketing.exception.ResourceNotFoundException;import com.digitalbase.ticketing.model.*;import com.digitalbase.ticketing.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.List;import java.util.Optional;import java.util.stream.Collectors;@Service@RequiredArgsConstructorpublic class ClientProductServiceImpl implements ClientProductService {    private final ClientProductRepository clientProductRepository;    private final TicketRepository ticketRepository;    private final UserRepository userRepository;    private final ProductRepository productRepository;    private final ProductPlanRepository productPlanRepository;    @Override    @Transactional    public ClientProductResponse assignProductToClient(ClientProductRequest request) {        User user = userRepository.findById(request.getUserId())                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        Product product = productRepository.findById(request.getProductId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found"));        // 💡 [အပြောင်းအလဲ - ၁] Request က ပို့လိုက်တဲ့ planId ဖြင့် ProductPlan Entity ကို ရှာပါမည်        ProductPlan productPlan = productPlanRepository.findById(request.getPlanId())                .orElseThrow(() -> new ResourceNotFoundException("Product plan not found"));        Instant now = Instant.now();        Instant newStartDate = now;        // 💡 [အပြောင်းအလဲ - ၂] Frontend မှ Duration / Minutes မပို့ပါက Database ထဲရှိ Plan ရဲ့တန်ဖိုးကို အလိုအလျောက် ယူပါမည်        long planDurationDays = request.getDurationDays() != null ? request.getDurationDays() : productPlan.getDurationDays();        int totalMinutes = request.getTotalMinutes() != null ? request.getTotalMinutes() : productPlan.getTotalMinutes();        // 🧠 [Business Logic] အရင် Plan အဟောင်း ရှိ/မရှိ နှင့် သက်တမ်းကုန်/မကုန် စစ်ဆေးခြင်း        Optional<ClientProduct> latestPlan = clientProductRepository.findTopByUserIdAndProductIdOrderByPlanEndDateDesc(user.getId(), product.getId());        if (latestPlan.isPresent()) {            Instant lastEndDate = latestPlan.get().getPlanEndDate();            // ယခင် Plan သည် သက်တမ်းမကုန်သေးပါက (Active ဖြစ်နေပါက)            if (lastEndDate != null && lastEndDate.isAfter(now)) {                newStartDate = lastEndDate; // အသစ်၏ Start Date ကို အဟောင်းကုန်မည့်ရက်မှ စတင်မည်            }        }        // 📅 အသစ်၏ End Date ကို တွက်ချက်ခြင်း        Instant newEndDate = newStartDate.plus(planDurationDays, java.time.temporal.ChronoUnit.DAYS);        ClientProduct clientProduct = ClientProduct.builder()                .user(user)                .product(product)                .productPlan(productPlan)                .purchasedDate(now)                .planStartDate(newStartDate)                .planEndDate(newEndDate)                .totalMinutes(totalMinutes)      // 👈 ပြင်ဆင်ထားသော variable ကို သုံးပါ                .availableMinutes(totalMinutes)  // 👈 ပြင်ဆင်ထားသော variable ကို သုံးပါ                .build();        clientProduct.setStatus(getDynamicStatus(clientProduct));        ClientProduct savedClientProduct = clientProductRepository.save(clientProduct);        return mapToResponse(savedClientProduct);    }    @Override    @Transactional    public ClientProductResponse renewProductPlan(ClientProductRequest request) {        User user = userRepository.findById(request.getUserId())                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        Product product = productRepository.findById(request.getProductId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found"));        // 💡 [အပြောင်းအလဲ - ၁] Request က ပို့လိုက်တဲ့ planId ဖြင့် ProductPlan Entity ကို အရင်ရှာပါမည်        ProductPlan productPlan = productPlanRepository.findById(request.getPlanId())                .orElseThrow(() -> new ResourceNotFoundException("Product plan not found"));        Instant now = Instant.now();        Instant newStartDate = now;        // 💡 [အပြောင်းအလဲ - ၂] Frontend မှ ရက် သို့မဟုတ် မိနစ် မပို့ပါက Database ထဲရှိ Plan ရဲ့တန်ဖိုးကို အလိုအလျောက် ယူပါမည်        long planDurationDays = request.getDurationDays() != null ? request.getDurationDays() : productPlan.getDurationDays();        int totalMinutes = request.getTotalMinutes() != null ? request.getTotalMinutes() : productPlan.getTotalMinutes();        // 🔍 Database ထဲမှ ဤ Customer ၏ နောက်ဆုံးဝယ်ထားသော Plan ကို ရှာဖွေခြင်း        Optional<ClientProduct> latestPlan = clientProductRepository.findTopByUserIdAndProductIdOrderByPlanEndDateDesc(user.getId(), product.getId());        if (latestPlan.isPresent()) {            Instant lastEndDate = latestPlan.get().getPlanEndDate();            // 💡 ယခင် Plan သည် သက်တမ်းမကုန်သေးပါက၊ ထိုရက်စွဲကို Start Date အသစ်အဖြစ် သတ်မှတ်မည်            if (lastEndDate != null && lastEndDate.isAfter(now)) {                newStartDate = lastEndDate;            }        }        // 📅 အသစ်ဝယ်လိုက်သော သက်တမ်း (ရက်အရေအတွက်) ကို Start Date အသစ်ပေါ်တွင် ပေါင်းထည့်မည်        Instant newEndDate = newStartDate.plus(planDurationDays, java.time.temporal.ChronoUnit.DAYS);        ClientProduct renewedPlan = ClientProduct.builder()                .user(user)                .product(product)                .productPlan(productPlan)                .purchasedDate(now)                .planStartDate(newStartDate)                .planEndDate(newEndDate)                .totalMinutes(totalMinutes)      // 👈 ပြင်ဆင်ထားသော variable ကို သုံးပါ                .availableMinutes(totalMinutes)  // 👈 ပြင်ဆင်ထားသော variable ကို သုံးပါ                .build();        renewedPlan.setStatus(getDynamicStatus(renewedPlan));        ClientProduct savedPlan = clientProductRepository.save(renewedPlan);        return mapToResponse(savedPlan);    }    @Override    @org.springframework.transaction.annotation.Transactional(readOnly = true)    public TopNavResponse getTopNavSummary(String email, Long productId) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<ClientProduct> products;        // 💡 Frontend မှ productId လှမ်းပို့ပါက သက်ဆိုင်ရာ Product ကိုသာ ဆွဲထုတ်မည်        if (productId != null) {            products = clientProductRepository.findAllByUserIdAndProductId(user.getId(), productId);        } else {            // မပို့ပါက Product အားလုံးကို ဆွဲထုတ်မည်            products = clientProductRepository.findAllByUserId(user.getId());        }        int totalMins = 0;        int availableMins = 0;        // 💡 လက်ရှိ သုံးလို့ရနေသော (ACTIVE နှင့် EXPIRING_SOON) များကိုသာ စစ်ထုတ်ပြီး ပေါင်းပါမည်        for (ClientProduct cp : products) {            ProductStatus dynamicStatus = getDynamicStatus(cp);            if (dynamicStatus == ProductStatus.ACTIVE || dynamicStatus == ProductStatus.EXPIRING_SOON) {                totalMins += (cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0);                availableMins += (cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0);            }        }        int displayAvailableMins = Math.max(0, availableMins);        String headerText = String.format("Available: %dHrs %d Mins/%d Hrs Credit",                displayAvailableMins / 60, displayAvailableMins % 60, totalMins / 60);        return TopNavResponse.builder()                .headerAvailableCreditText(headerText)                .fullName(user.getFullName())                .build();    }    @Override    @org.springframework.transaction.annotation.Transactional(readOnly = true)    public DashboardSummaryResponse getDashboardSummary(String email, Long productId) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<ClientProduct> products;        if (productId != null) {            products = clientProductRepository.findAllByUserIdAndProductId(user.getId(), productId);        } else {            products = clientProductRepository.findAllByUserId(user.getId());        }        if (products.isEmpty()) {            return DashboardSummaryResponse.builder().build();        }        // 💡 လက်ရှိသုံး၍ရသော Plan များအတွက်သာ        int activeTotalMins = 0;        int activeAvailableMins = 0;        // 💡 အနာဂတ် Plan များအတွက်        int upcomingMins = 0;        int activeProductCount = 0;        ClientProduct activeProduct = null;        ClientProduct nearestExpiringProduct = null;        for (ClientProduct cp : products) {            ProductStatus dynamicStatus = getDynamicStatus(cp);            int cpTotal = cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0;            int cpAvail = cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0;            // 🟢 လက်ရှိသုံးနေသော (ACTIVE / EXPIRING_SOON) များကိုသာ ပေါင်းမည်            if (dynamicStatus == ProductStatus.ACTIVE || dynamicStatus == ProductStatus.EXPIRING_SOON) {                activeTotalMins += cpTotal;                activeAvailableMins += cpAvail;                activeProductCount++;                if (activeProduct == null) activeProduct = cp;                if (nearestExpiringProduct == null || (cp.getPlanEndDate() != null && nearestExpiringProduct.getPlanEndDate() != null && cp.getPlanEndDate().isBefore(nearestExpiringProduct.getPlanEndDate()))) {                    nearestExpiringProduct = cp;                    activeProduct = cp;                }            }            // 🔵 အနာဂတ်အတွက် ဝယ်ထားသော Plan (UPCOMING) ကို သီးသန့်ပေါင်းမည်            else if (dynamicStatus == ProductStatus.UPCOMING) {                upcomingMins += cpAvail;            }        }        // ⏱️ မိနစ်များ တွက်ချက်ခြင်း (Hours ဖြင့်စားခြင်း မရှိတော့ပါ)        int displayAvailableMins = Math.max(0, activeAvailableMins);        int usedMinsTotal = activeAvailableMins >= 0 ? activeTotalMins - activeAvailableMins : activeTotalMins;        int extraMinsTotal = activeAvailableMins < 0 ? Math.abs(activeAvailableMins) : 0;        long daysRemaining = 0;        String expiryString = "N/A";        if (nearestExpiringProduct != null && nearestExpiringProduct.getPlanEndDate() != null) {            daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(Instant.now(), nearestExpiringProduct.getPlanEndDate());            if (daysRemaining < 0) daysRemaining = 0;            java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("'Expired in' MMM d")                    .withZone(java.time.ZoneId.systemDefault());            expiryString = formatter.format(nearestExpiringProduct.getPlanEndDate());        }        Instant startOfToday = java.time.LocalDate.now().atStartOfDay(java.time.ZoneId.systemDefault()).toInstant();        List<Long> cpIds = products.stream().map(ClientProduct::getId).collect(Collectors.toList());        long totalSubmitted = 0, todaySubmitted = 0, totalResolved = 0, todayResolved = 0;        if (!cpIds.isEmpty()) {            List<TicketStatus> submittedStatuses = java.util.Arrays.asList(TicketStatus.SUBMITTED);            totalSubmitted = ticketRepository.countByClientProductIdInAndStatusIn(cpIds, submittedStatuses);            todaySubmitted = ticketRepository.countByClientProductIdInAndStatusInAndCreatedAtAfter(cpIds, submittedStatuses, startOfToday);            List<TicketStatus> resolvedStatuses = java.util.Arrays.asList(TicketStatus.RESOLVED, TicketStatus.CLOSED);            totalResolved = ticketRepository.countByClientProductIdInAndStatusIn(cpIds, resolvedStatuses);            todayResolved = ticketRepository.countByClientProductIdInAndStatusInAndUpdatedAtAfter(cpIds, resolvedStatuses, startOfToday);        }        return DashboardSummaryResponse.builder()                // ⏱️ Hours များကို ဖယ်ရှားပြီး မိနစ်များကို တိုက်ရိုက် သုံးထားပါသည်                .purchasedMinutes(activeTotalMins)                .usedMinutes(usedMinsTotal)                .availableMinutes(displayAvailableMins)                .extraMinutes(extraMinsTotal)                .upcomingMinutes(upcomingMins) // 👈 Upcoming မိနစ်များ                // 💡 [ပြောင်းလဲချက်] cp.getSupportPlan() အစား cp.getProductPlan().getPlanName() ကို အသုံးပြုထားပါသည်                .supportPlanName(activeProduct != null ? activeProduct.getProductPlan().getPlanName() : "No Active Plan")                .status(activeProduct != null ? getDynamicStatus(activeProduct).name() : "DISABLED")                .purchasedDate(activeProduct != null ? activeProduct.getPurchasedDate() : null)                .planEndDate(activeProduct != null ? activeProduct.getPlanEndDate() : null)                .slaHoursCard(DashboardSummaryResponse.SlaHoursCard.builder()                        .totalMinutes(activeTotalMins)                        .usedMinutes(usedMinsTotal)                        .remainingMinutes(displayAvailableMins)                        .expiryDateText(expiryString)                        .daysRemaining(daysRemaining)                        .build())                .submittedTicketsCard(DashboardSummaryResponse.TicketStatCard.builder()                        .totalCount((int) totalSubmitted)                        .todayCount((int) todaySubmitted)                        .build())                .resolvedTicketsCard(DashboardSummaryResponse.TicketStatCard.builder()                        .totalCount((int) totalResolved)                        .todayCount((int) todayResolved)                        .build())                .activeProductCard(DashboardSummaryResponse.ProductStatCard.builder()                        .activeCount(activeProductCount)                        .totalCount(productId != null ? 1 : (int) products.stream().map(cp -> cp.getProduct().getId()).distinct().count())                        .expiryDateText(expiryString)                        .daysRemaining(daysRemaining)                        .build())                .build();    }    @Override    public MyProductDashboardResponse getMyProducts(String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<ClientProduct> clientProducts = clientProductRepository.findAllByUserId(user.getId());        // 💡 [Fix 1] Row အရေအတွက် (ဥပမာ ၄) ကို မရေတွက်ဘဲ၊ Unique ဖြစ်သော Product အမည် အရေအတွက် (ဥပမာ ၂) ကိုသာ ရေတွက်မည်        int totalUniqueProducts = (int) clientProducts.stream()                .map(cp -> cp.getProduct().getId())                .distinct()                .count();        // 💡 [Fix 2] Unique ဖြစ်သော Active Product အရေအတွက်ကိုသာ ရေတွက်မည်        int activeProducts = (int) clientProducts.stream()                .filter(cp -> {                    ProductStatus status = getDynamicStatus(cp);                    return status == ProductStatus.ACTIVE || status == ProductStatus.EXPIRING_SOON;                })                .map(cp -> cp.getProduct().getId())                .distinct()                .count();        // 🟢 [Fix 3] ACTIVE နှင့် EXPIRING_SOON ဖြစ်သော Plan များ၏ 'ကျန်ရှိသော' မိနစ်များကိုသာ ပေါင်းမည်        int totalSlaHours = clientProducts.stream()                .filter(cp -> {                    ProductStatus status = getDynamicStatus(cp);                    return status == ProductStatus.ACTIVE || status == ProductStatus.EXPIRING_SOON;                })                .mapToInt(ClientProduct::getAvailableMinutes)                .sum() / 60;        // 🔵 [Fix 4] UPCOMING ဖြစ်သော Plan များ၏ မိနစ်များကို သီးသန့် ပေါင်းမည်        int upcomingSlaHours = clientProducts.stream()                .filter(cp -> getDynamicStatus(cp) == ProductStatus.UPCOMING)                .mapToInt(ClientProduct::getAvailableMinutes)                .sum() / 60;        int extraUsageHours = clientProducts.stream()                .filter(cp -> cp.getAvailableMinutes() < 0)                .mapToInt(cp -> Math.abs(cp.getAvailableMinutes()))                .sum() / 60;        List<ClientProductResponse> productResponses = clientProducts.stream()                .map(this::mapToResponse)                .collect(Collectors.toList());        return MyProductDashboardResponse.builder()                .totalProducts(totalUniqueProducts)                .totalSlaHours(totalSlaHours)                .upcomingSlaHours(upcomingSlaHours)                .activeProducts(activeProducts)                .extraUsageHours(extraUsageHours)                .products(productResponses)                .build();    }    @Override    public ClientProductDetailResponse getProductDetailsByProductId(Long productId, String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        // 💡 Join Table မလိုပါ။ User ID နှင့် Product ID တူသော Plan အားလုံးကို ဆွဲထုတ်လိုက်ခြင်း ဖြစ်ပါသည်။        List<ClientProduct> allPlans = clientProductRepository.findAllByUserIdAndProductId(user.getId(), productId);        if (allPlans.isEmpty()) {            throw new ResourceNotFoundException("No SLA plans found for this product.");        }        // Product အချက်အလက်များကို ပထမဆုံး Plan မှ ဆွဲယူပါမည် (မည်သည့် Plan မှ ယူယူ အတူတူပင်ဖြစ်သည်)        Product product = allPlans.get(0).getProduct();        // 🟢 Current Plan (ACTIVE သို့မဟုတ် EXPIRING_SOON ကို ရှာခြင်း)        SlaPlanInfo currentPlan = allPlans.stream()                .filter(cp -> getDynamicStatus(cp) == ProductStatus.ACTIVE || getDynamicStatus(cp) == ProductStatus.EXPIRING_SOON)                .findFirst()                .map(this::mapToSlaPlanInfo)                .orElse(null);        // 🔵 Upcoming Plans (UPCOMING အားလုံးကို ရှာခြင်း)        List<SlaPlanInfo> upcomingPlans = allPlans.stream()                .filter(cp -> getDynamicStatus(cp) == ProductStatus.UPCOMING)                .map(this::mapToSlaPlanInfo)                .collect(Collectors.toList());        // ⚪ Past Plans (EXPIRED အားလုံးကို ရှာခြင်း)        List<SlaPlanInfo> pastPlans = allPlans.stream()                .filter(cp -> getDynamicStatus(cp) == ProductStatus.EXPIRED)                .map(this::mapToSlaPlanInfo)                .collect(Collectors.toList());        return ClientProductDetailResponse.builder()                .productId(product.getId())                .productName(product.getName())                .productDescription(product.getDescription())                .productType(product.getProductType())                .imageUrl(product.getImageUrl())                .currentPlan(currentPlan)                .upcomingPlans(upcomingPlans)                .pastPlans(pastPlans)                .build();    }    // Helper Method (မိနစ်များ တွက်ချက်ခြင်း)    private SlaPlanInfo mapToSlaPlanInfo(ClientProduct cp) {        int availMins = cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0;        int totalMins = cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0;        int remainMinsTotal = Math.max(availMins, 0);        int extraMinsTotal = availMins < 0 ? Math.abs(availMins) : 0;        int usedMinsTotal = availMins >= 0 ? totalMins - availMins : totalMins;        long daysRemaining = 0;        if (cp.getPlanEndDate() != null) {            daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(java.time.Instant.now(), cp.getPlanEndDate());            if(daysRemaining < 0) daysRemaining = 0;        }        return SlaPlanInfo.builder()                .clientProductId(cp.getId())                // 💡 [ပြောင်းလဲချက်] cp.getSupportPlan() အစား cp.getProductPlan().getPlanName() ကို အသုံးပြုထားပါသည်                .supportPlan(cp.getProductPlan().getPlanName())                .status(getDynamicStatus(cp).name())                .purchasedDate(cp.getPurchasedDate() != null ? cp.getPurchasedDate().toString() : null)                .planStartDate(cp.getPlanStartDate() != null ? cp.getPlanStartDate().toString() : null)                .planEndDate(cp.getPlanEndDate() != null ? cp.getPlanEndDate().toString() : null)                .totalMinutes(totalMins)                .remainingMinutes(remainMinsTotal)                .usedMinutes(usedMinsTotal)                .extraMinutes(extraMinsTotal)                .daysRemaining(daysRemaining)                .build();    }    @Override    public Page<ProductTicketDto> getProductRelatedTickets(            Long clientProductId, String email,            String statusFilter, String startDateStr, String endDateStr,            int page, int size) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        ClientProduct cp;        // Admin ဖြစ်ရင် ကိုယ်ပိုင် Product ဟုတ်/မဟုတ် (userId) စစ်စရာမလိုပါ        if (user.getRole().name().equals("ADMIN")) {            cp = clientProductRepository.findById(clientProductId)                    .orElseThrow(() -> new ResourceNotFoundException("Product not found"));        } else {            // Client ဖြစ်မှသာ သူပိုင်တဲ့ Product ဟုတ်/မဟုတ် စစ်ဆေးမည်            cp = clientProductRepository.findByIdAndUserId(clientProductId, user.getId())                    .orElseThrow(() -> new ResourceNotFoundException("Product not found or access denied"));        }        Pageable pageable = PageRequest.of(page, size, Sort.by("createdAt").descending());        // 🎯 Filter တန်ဖိုးများကို String မှ Enum / Instant သို့ ပြောင်းလဲခြင်း        TicketStatus status = null;        if (statusFilter != null && !statusFilter.isEmpty() && !statusFilter.equalsIgnoreCase("ALL")) {            try {                status = TicketStatus.valueOf(statusFilter.toUpperCase());            } catch (IllegalArgumentException e) {                // Ignore format error            }        }        Instant startDate = null;        Instant endDate = null;        try {            if (startDateStr != null && !startDateStr.isEmpty()) {                startDate = Instant.parse(startDateStr);            }            if (endDateStr != null && !endDateStr.isEmpty()) {                endDate = Instant.parse(endDateStr);            }        } catch (Exception e) {            // Ignore parse error        }        // =========================================================================        // 🎯 [အပြောင်းအလဲ] Specification ကို အသုံးပြု၍ Query တည်ဆောက်ခြင်း        // =========================================================================        Specification<Ticket> spec = Specification.where(TicketSpecification.belongsToClientProduct(cp.getId()));        if (status != null) {            spec = spec.and(TicketSpecification.hasStatus(status));        }        if (startDate != null) {            spec = spec.and(TicketSpecification.createdAfter(startDate));        }        if (endDate != null) {            spec = spec.and(TicketSpecification.createdBefore(endDate));        }        // 🎯 Specification ကို အသုံးပြု၍ Repository မှ Data ဆွဲထုတ်ခြင်း        Page<Ticket> tickets = ticketRepository.findAll(spec, pageable);        return tickets.map(t -> {            // 🎯 [အပြောင်းအလဲ] Assignments များထဲမှ Developer နာမည်များကို ဆွဲထုတ်ပြီး ကော်မာ(,) ဖြင့် ဆက်ပေးခြင်း            String assignedNames = "Pending";            if (t.getAssignments() != null && !t.getAssignments().isEmpty()) {                assignedNames = t.getAssignments().stream()                        .map(a -> a.getDeveloper().getFullName())                        .collect(Collectors.joining(", "));            }            return ProductTicketDto.builder()                    .ticketId("DB-TK" + t.getId())                    .status(t.getStatus() != null ? t.getStatus().name() : "UNKNOWN")                    .issueType(t.getIssueType() != null ? t.getIssueType().name() : "UNKNOWN")                    .assignedTeam(assignedNames) // 👈 ယခင် t.getDeveloper() အစား ပြင်ဆင်ထားသော String ကို ထည့်ပါ                    .priority(t.getPriority() != null ? t.getPriority().name() : "Normal")                    .timeUsedMinutes(t.getSpentMinutes() != null ? t.getSpentMinutes() : 0)                    .build();        });    }    // 👈 [Dynamic Status] - လုံးဝ မှန်ကန်ပါသည်    private ProductStatus getDynamicStatus(ClientProduct cp) {        Instant now = Instant.now();        if (cp.getPlanStartDate() != null && cp.getPlanStartDate().isAfter(now)) {            return ProductStatus.UPCOMING;        }        if (cp.getPlanEndDate() != null && cp.getPlanEndDate().isBefore(now)) {            return ProductStatus.EXPIRED;        }        if (cp.getPlanEndDate() != null) {            long daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(now, cp.getPlanEndDate());            if (daysRemaining <= 7) {                return ProductStatus.EXPIRING_SOON;            }        }        return ProductStatus.ACTIVE;    }    // 👈 [mapToResponse] - လုံးဝ မှန်ကန်ပါသည်    private ClientProductResponse mapToResponse(ClientProduct cp) {        return ClientProductResponse.builder()                .id(cp.getId())                .productName(cp.getProduct().getName())                .productDescription(cp.getProduct().getDescription())                .productType(cp.getProduct().getProductType())                .imageUrl(cp.getProduct().getImageUrl())                // 💡 [ပြောင်းလဲချက်] cp.getSupportPlan() အစား cp.getProductPlan().getPlanName() ကို အသုံးပြုထားပါသည်                .supportPlan(cp.getProductPlan().getPlanName())                .purchasedDate(cp.getPurchasedDate())                .planEndDate(cp.getPlanEndDate())                .availableMinutes(cp.getAvailableMinutes())                .totalMinutes(cp.getTotalMinutes())                .status(getDynamicStatus(cp).name())                .build();    }}